import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Add Todos', () => {
  test('Renders input, button, and list', async () => {
    const { container: root } = render(<App />);
    if (!root.querySelector('#new-todo')) throw new Error('Missing #new-todo input');
if (!root.querySelector('#add')) throw new Error('Missing #add button');
if (!root.querySelector('#todos')) throw new Error('Missing #todos ul');
  });

  test('Typing and clicking Add appends a todo', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#new-todo');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'Buy milk');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
root.querySelector('#add').click();
await tick();
const items = root.querySelectorAll('#todos li');
if (items.length !== 1) throw new Error('Expected 1 todo, got ' + items.length);
if (!items[0].textContent.includes('Buy milk')) throw new Error('Todo text should be "Buy milk"');
  });

  test('Input clears after adding', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#new-todo');
if (input.value !== '') throw new Error('Input should be empty after adding');
  });

  test('Adds multiple todos', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#new-todo');
const btn = root.querySelector('#add');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'Walk dog');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
setter.call(input, 'Write tests');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
const items = root.querySelectorAll('#todos li');
if (items.length < 3) throw new Error('Expected at least 3 todos, got ' + items.length);
  });

  test('Empty input is ignored', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#new-todo');
const btn = root.querySelector('#add');
const before = root.querySelectorAll('#todos li').length;
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, '   ');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
const after = root.querySelectorAll('#todos li').length;
if (after !== before) throw new Error('Whitespace-only input should not add a todo');
  });
});
